/* Study tools: local, transparent recommendations; no simulated human reviewers. */
(()=>{'use strict';
const PLUS_KEY='compass-study-plus-v1',subjects=['국어','수학','영어','통합사회','통합과학','한국사','과학탐구실험·정보','예체능·기술가정'];
const causes={'문제 이해':'조건을 쉬운 문장으로 바꾸고, 무엇을 구하는지 한 줄로 써봐.','개념':'교과서에서 필요한 개념 하나와 적용 조건을 확인해봐.','풀이 시작':'대표 예제의 첫 단계와 이 문제의 공통점을 찾아봐.','계산·표현':'틀린 줄을 찾아 계산·단위·표현을 다시 확인해봐.','시간':'막힌 지점을 표시하고, 시간 제한 없이 먼저 해결해봐.'};
const routes={국어:['지문·작품을 읽고 핵심을 한 문장으로 적기','정답의 근거가 되는 문장 표시하기','틀린 선지 하나를 고쳐 설명하기'],수학:['개념과 적용 조건을 내 말로 설명하기','대표 문제 하나를 답 없이 시작하기','막힌 줄을 확인하고 처음부터 다시 풀기'],영어:['문장 속 모르는 단어 3개 확인하기','주어·동사·수식어를 구분해 해석하기','핵심 문장을 보지 않고 다시 써보기'],통합사회:['헷갈리는 개념 두 가지의 차이 쓰기','교과서 사례를 개념에 연결하기','판단 근거를 한 문장으로 설명하기'],통합과학:['오늘 배운 현상을 그림이나 말로 설명하기','그래프의 축·단위·변인을 확인하기','조건이 달라질 때 결과 예상하기'],한국사:['원인→사건→결과를 세 칸으로 정리하기','사료 속 인물·제도·시대 단서 찾기','책을 덮고 사건 순서 말하기'],'과학탐구실험·정보':['탐구 질문과 예상 결과 적기','관찰한 사실과 내 해석을 구분하기','자료 출처와 확인할 질문 기록하기'],'예체능·기술가정':['과제 조건과 준비물 확인하기','어려운 부분 하나를 나누어 연습하기','다음 연습과 제출 일정을 확인하기']};
const clean=(v,n=800)=>String(v??'').slice(0,n),obj=v=>v&&typeof v==='object'&&!Array.isArray(v),validKey=k=>!['__proto__','constructor','prototype'].includes(k),addDays=(date,n)=>new Date(Date.parse(date+'T12:00Z')+n*86400000).toISOString().slice(0,10);
function restorePlus(raw){const p={courses:{},exams:{},reviews:{},questions:[],logs:[],mode:40,subject:'수학',goal:''};try{const v=JSON.parse(raw);if(!obj(v))return p;if([10,40,80].includes(v.mode))p.mode=v.mode;if(subjects.includes(v.subject))p.subject=v.subject;p.goal=clean(v.goal,120);for(const [k,x]of Object.entries(v.courses||{}).slice(0,60))if(validKey(k)&&obj(x))p.courses[k]={book:clean(x.book,80),unit:clean(x.unit,100),pages:clean(x.pages,40)};for(const [k,x]of Object.entries(v.exams||{}).slice(0,200))if(validKey(k)&&obj(x))p.exams[k]={rubric:clean(x.rubric),steps:Array.isArray(x.steps)?x.steps.slice(0,30).filter(obj).map(s=>({title:clean(s.title,120),done:!!s.done})):[]};for(const [k,x]of Object.entries(v.reviews||{}).slice(0,200))if(validKey(k)&&obj(x))p.reviews[k]={cause:Object.hasOwn(causes,x.cause)?x.cause:'개념',source:clean(x.source,120),due:valid(x.due)?x.due:today(),stage:Math.min(3,Math.max(0,Math.trunc(Number(x.stage)||0))),last:clean(x.last,20),attempts:Array.isArray(x.attempts)?x.attempts.filter(a=>obj(a)&&valid(a.date)&&['alone','hint','hard'].includes(a.result)).slice(-30).map(a=>({date:a.date,result:a.result})):[]};if(Array.isArray(v.questions))p.questions=v.questions.filter(x=>obj(x)&&typeof x.id==='string'&&valid(x.date)).slice(-100).map(x=>({id:clean(x.id,80),date:x.date,title:clean(x.title,200),answer:clean(x.answer),done:!!x.done}));if(Array.isArray(v.logs))p.logs=v.logs.filter(x=>obj(x)&&valid(x.date)).slice(-200).map(x=>({date:x.date,goal:clean(x.goal,120),feeling:['쉬움','적당함','버거움'].includes(x.feeling)?x.feeling:'적당함',explanation:clean(x.explanation,400)}))}catch{}return p}
let plus;try{plus=restorePlus(localStorage.getItem(PLUS_KEY))}catch{plus=restorePlus(null)}
function persist(){try{localStorage.setItem(PLUS_KEY,JSON.stringify(plus));return true}catch{notice('저장하지 못했어. 브라우저 저장 공간을 확인해줘.');return false}}
const reviewMeta=x=>plus.reviews[x.id]||{cause:'개념',source:'',due:x.date,stage:0,attempts:[]};
function nextReview(meta,result,date=today()){const stage=result==='alone'?Math.min(3,meta.stage+1):0;return {...meta,stage,due:addDays(date,result==='alone'?[1,3,7][Math.min(meta.stage,2)]:1),last:result,attempts:[...(meta.attempts||[]),{date,result}].slice(-30)}}
function examStage(x){const d=gap(x.date);return d<0?'마감이 지났어. 완료·일정 변경 여부를 확인해줘.':d<=2?'핵심 개념과 반복 실수를 확인할 때야.':d<=7?'오답·서술형과 짧은 시간 연습을 해봐.':d<=14?'대표 문제와 교과서 자료를 익혀보자.':'범위를 확인하고 어려운 개념부터 찾아보자.'}
function recommendations(){const a=[];for(const x of state.dates.filter(x=>!x.done)){const m=plus.exams[x.id],step=m?.steps.find(s=>!s.done);if(gap(x.date)<=21)a.push({title:x.title+(step?' · '+step.title:''),reason:gap(x.date)<0?'지난 마감 확인':gap(x.date)===0?'오늘 마감':'D-'+gap(x.date),go:'dates',score:gap(x.date)<0?0:gap(x.date)<=2?1:4,date:x.date})}for(const x of state.reviews.filter(x=>!x.done)){const m=reviewMeta(x);if(gap(m.due)<=0)a.push({title:'다시 풀기 · '+x.title,reason:'복습할 날이야',go:'review',score:2,date:m.due})}for(const x of state.tasks.filter(x=>!x.done&&x.date===today()))a.push({title:x.title,reason:'내가 정한 오늘 할 일',go:'today',score:3,date:x.date});const nd=typeof FC_CAL!=='undefined'?FC_CAL.nextSchoolDay(today()):addDays(today(),1),d=(new Date(nd+'T12:00Z').getUTCDay()+6)%7,nl=gap(nd)===1?'내일':nd.slice(5).replace('-','/')+'(다음 등교)';if(d<5&&state.table[d].some(Boolean))a.push({title:nl+' '+state.table[d].filter(Boolean).slice(0,3).join(' · ')+' 준비',reason:state.bags[d]||'교재와 준비물을 확인해봐',go:typeof FC_CAL!=='undefined'?'week':'table',score:5,date:nd});return a.sort((x,y)=>x.score-y.score||x.date.localeCompare(y.date)).slice(0,3)}
function todayExtra(){const a=recommendations(),pending=state.tasks.filter(x=>!x.done&&x.date<today());return `<section class="card next-card"><div class="section-title"><h2>오늘은 이 3개부터</h2></div>${a.length?a.map((x,i)=>`<div class="next-item"><b class="number">${i+1}</b><span><strong>${esc(x.title)}</strong><small>${esc(x.reason)}</small></span><button ${x.go==='today'?'data-today-task':'data-go="'+x.go+'"'}>보기 →</button></div>`).join(''):'<p>오늘 할 일이나 시험 일정을 넣으면, 마감과 복습을 함께 챙겨줄게.</p><div class="actions"><button data-go="dates">시험·과제 넣기</button><button data-go="review">복습할 것 적기</button></div>'}</section>${pending.length?`<details class="card"><summary>지난 할 일 ${pending.length}개 · 다시 정리하기</summary>${pending.map(x=>`<div class="row"><span>${esc(x.title)}</span><button data-carry="${esc(x.id)}">오늘로</button><button data-finish="${esc(x.id)}">정리 완료</button></div>`).join('')}</details>`:''}`}
function coursePanel(){const names=[...new Set([...state.table.flat().filter(Boolean),...Object.keys(plus.courses)])].filter(validKey);return `<details class="card" id="course-panel"><summary>📖 수업에 교재·단원 연결하기</summary><p class="muted">실제 학교 교과서와 진도를 적어줘. 시간표 과목과 같은 이름으로 연결돼.</p>${names.length?names.map(n=>{const c=plus.courses[n]||{};const sci=Object.entries(plus.courses).find(([k,v])=>typeof FC_CURRICULUM!=='undefined'&&FC_CURRICULUM.baseOf(k)==='통합과학'&&v.book),cur=typeof FC_CURRICULUM!=='undefined'?FC_CURRICULUM.lookup(n,null,null,{book:c.book,prefer:sci?sci[1].book:''}):null,inList=cur&&cur.flat.includes(c.unit),bks=cur&&cur.books&&cur.books.length?cur.books:null,bookIn=bks&&bks.some(b=>b.name===c.book),bookSel=c.book?(bookIn?c.book:'__custom'):(bks?bks[0].name:'');return `<form data-plus="course" data-subject="${esc(n)}" class="subcard"><h3>${esc(n)}${cur?` <small class="muted">${esc(cur.course)}</small>`:''}</h3>${bks?`<label>교과서 (표지를 보고 골라줘)<select name="book">${bks.map((b,i)=>`<option value="${esc(b.name)}" ${b.name===bookSel?'selected':''}>${esc(b.name)}${b.tag?' — '+esc(b.tag):''}</option>`).join('')}<option value="__custom" ${bookSel==='__custom'?'selected':''}>목록에 없음 · 직접 적기</option></select></label><label class="book-custom" ${bookSel==='__custom'?'':'hidden'}>교과서 직접 적기<input name="bookCustom" maxlength="80" value="${esc(bookIn?'':c.book)}" placeholder="출판사 · 저자"></label><p class="muted">'유력'은 서초고 시험 자료로 확인된 것, '추정'·'추천순'은 아직 확인 전이야.</p>`:`<label>교재·출판사<input name="book" maxlength="80" value="${esc(c.book||'')}" placeholder="예: 교과서 출판사"></label>`}${cur&&cur.extra?`<p class="muted">📎 ${esc(cur.extra)}</p>`:''}${cur&&cur.flat.length?`<label>지금 배우는 단원<select name="unit"><option value="">고르기</option>${cur.flat.map(u=>`<option ${u===c.unit?'selected':''}>${esc(u)}</option>`).join('')}<option value="__custom" ${c.unit&&!inList?'selected':''}>직접 적기</option></select></label><label class="unit-custom" ${c.unit&&!inList?'':'hidden'}>직접 적는 단원<input name="unitCustom" maxlength="100" value="${esc(inList?'':c.unit)}" placeholder="목록에 없으면 여기에"></label>`:`<label>지금 배우는 단원<input name="unit" maxlength="100" value="${esc(c.unit)}" placeholder="${cur&&cur.byPublisher?'교과서마다 단원이 달라. 교과서 목차를 보고 적어줘':''}"></label>`}<label>페이지<input name="pages" maxlength="40" value="${esc(c.pages)}" placeholder="예: 35~41쪽"></label><button class="primary">수업 정보 저장</button></form>`}).join(''):'<p>위 시간표에 과목을 입력한 뒤 이 메뉴를 다시 열어줘.</p>'}</details>`}
function examPanels(){return state.dates.filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>{const m=plus.exams[x.id]||{steps:[],rubric:''};return `<details class="card"><summary>${x.kind==='수행평가'?'🎤':'🧩'} ${esc(x.title)} · 준비 나누기</summary><p class="muted">${x.kind==='시험'?examStage(x):'학교 안내문에서 제출 형식과 채점 기준을 확인해줘.'}</p>${m.steps.length?`<p>${m.steps.filter(s=>s.done).length}/${m.steps.length}단계 완료</p><progress max="${m.steps.length}" value="${m.steps.filter(s=>s.done).length}"></progress>`:''}${m.steps.map((s,i)=>`<label class="step-check"><input type="checkbox" data-step="${esc(x.id)}" data-index="${i}" ${s.done?'checked':''}>${esc(s.title)}</label>`).join('')}<form data-plus="exam" data-id="${esc(x.id)}"><label>시험·마감 날짜<input name="date" type="date" required value="${esc(x.date)}"></label><label>추가할 ${x.kind==='시험'?'단원·페이지·문제':'준비 단계'} (한 줄에 하나)<textarea name="units" maxlength="2500" placeholder="${x.kind==='시험'?'1단원 개념 확인\n1단원 대표 문제\n오답 다시 풀기':'주제 결정\n자료·출처 확인\n초안 만들기\n연습\n제출 확인'}"></textarea></label><label>채점 기준·제출 형식 메모<textarea name="rubric" maxlength="800">${esc(m.rubric)}</textarea></label><button class="primary">계획 저장</button>${!m.steps.length?` <button type="button" data-template="${esc(x.id)}">기본 단계 넣기</button>`:''}</form></details>`}).join('')}
function reviewPanels(){return state.reviews.filter(x=>!x.done).map(x=>{const m=reviewMeta(x);return `<details class="card" ${gap(m.due)<=0?'open':''}><summary>🔁 ${esc(x.title)} · ${gap(m.due)<=0?'오늘 재도전':m.due+' 복습'}</summary><p class="muted">${esc(m.source)||esc(x.subject)} · ${esc(causes[m.cause]||causes['개념'])}</p><form data-plus="review" data-id="${esc(x.id)}"><label>어디서 막혔어?<select name="cause">${Object.keys(causes).map(c=>`<option ${c===m.cause?'selected':''}>${c}</option>`).join('')}</select></label><label>교재·페이지·문항<input name="source" maxlength="120" value="${esc(m.source)}" placeholder="예: 교과서 42쪽 3번"></label><label>다음 복습일<input name="due" type="date" required value="${esc(m.due)}"></label><button>복습 설정 저장</button></form><p><strong>답을 가리고 다시 풀어봤어?</strong></p><div class="actions">${[['alone','혼자 해결'],['hint','힌트로 해결'],['hard','아직 어려움']].map(([v,t])=>`<button data-result="${v}" data-id="${esc(x.id)}">${t}</button>`).join('')}</div>${m.attempts.length?`<p class="muted">최근 재도전 ${m.attempts.length}회 · 다음 복습 ${m.due}</p>`:''}</details>`}).join('')}
function learningPanel(){return `<details class="card"><summary>📚 과목별 공부 시작법 · 내 말로 설명하기</summary><label for="study-subject">오늘 공부할 과목</label><select id="study-subject" data-subject-choice>${subjects.map(s=>`<option ${plus.subject===s?'selected':''}>${s}</option>`).join('')}</select><ol class="learning-steps">${routes[plus.subject].map(s=>`<li>${s}</li>`).join('')}</ol><p class="muted">교과서나 가지고 있는 문제로 진행해줘. 시작이 어렵다면 첫 단계만 10분 해봐.</p><a href="https://www.ebsi.co.kr/" target="_blank" rel="noopener">EBSi에서 공식 강의·기출 찾아보기 ↗</a><form data-plus="reflection"><label>오늘 이해한 것을 내 말로<textarea name="explanation" required maxlength="400" placeholder="배운 개념과 사용할 수 있는 상황을 적어봐."></textarea></label><label>오늘 분량은 어땠어?<select name="feeling"><option>적당함</option><option>쉬움</option><option>버거움</option></select></label><button class="primary">오늘 공부 기록</button></form></details>`}
function focusExtra(){return `<section class="card"><h2>🌱 오늘의 공부 크기</h2><div class="actions">${[[10,'🐾 가볍게 10분'],[40,'🌱 기본 40분'],[80,'🔥 집중 80분']].map(([n,t])=>`<button data-mode="${n}" class="${plus.mode===n?'active':''}">${t}</button>`).join('')}</div><p class="muted">${plus.mode===10?'떠올리기 2분 → 복습 6분 → 내일 준비 2분':plus.mode===40?'핵심 과목 20분 → 다른 과목 15분 → 정리 5분':'25분 → 휴식 5분 → 25분 → 휴식 5분 → 정리 20분'} · 학습 구성 제안이야. 아래 타이머는 별도로 선택해줘.</p><form data-plus="goal"><label>지금 할 한 가지<input name="goal" maxlength="120" value="${esc(plus.goal)}" placeholder="예: 수학 오답 2개를 혼자 풀기"></label><button>목표 저장</button></form></section>`}
function questionPanel(){return `<details class="card" id="questions"><summary>🙋 선생님께 물어볼 것</summary><form data-plus="question"><label>질문<input name="title" required maxlength="200" placeholder="어디까지 알겠고, 어디서 막혔는지 적어봐."></label><button>질문 모으기</button></form>${plus.questions.map(x=>`<details class="subcard"><summary>${x.done?'✅':'❔'} ${esc(x.title)}</summary><form data-plus="answer" data-id="${esc(x.id)}"><label>들은 설명·다음에 할 것<textarea name="answer" maxlength="800">${esc(x.answer)}</textarea></label><label class="step-check"><input name="done" type="checkbox" ${x.done?'checked':''}>질문 해결</label><button>답변 기록</button></form></details>`).join('')}</details>`}
function weekly(){const logs=plus.logs.filter(x=>gap(x.date)>=-6&&gap(x.date)<=0),attempts=Object.values(plus.reviews).flatMap(x=>x.attempts).filter(x=>gap(x.date)>=-6&&gap(x.date)<=0);return `<details class="card"><summary>🌿 최근 7일의 작은 변화</summary><div class="stats"><div><strong>${new Set(logs.map(x=>x.date)).size}</strong><span>공부를 기록한 날</span></div><div><strong>${attempts.length?Math.round(attempts.filter(x=>x.result==='alone').length/attempts.length*100)+'%':'—'}</strong><span>재도전 중 혼자 해결</span></div><div><strong>${logs.filter(x=>x.feeling==='버거움').length}</strong><span>분량이 버거웠던 기록</span></div></div><p class="muted">직접 입력한 기록 기준이야. 타이머만 켠 시간은 이해도에 포함하지 않아.</p>${logs.slice(-5).reverse().map(x=>`<p class="note"><b>${x.date} · ${esc(x.goal)||'오늘 공부'}</b><br>${esc(x.explanation)}<br><small>${esc(x.feeling)}</small></p>`).join('')}</details>`}
const baseRender=render;render=function(){baseRender();if(tab==='today'){root.insertAdjacentHTML('afterbegin',todayExtra());root.insertAdjacentHTML('beforeend',weekly());const entries=Object.entries(plus.courses).filter(([n,c])=>state.table[(new Date(today()+'T12:00Z').getUTCDay()+6)%7]?.includes(n)&&c.unit);if(entries.length)root.querySelector('.grid .card')?.insertAdjacentHTML('beforeend',entries.map(([n,c])=>`<p class="course-tag"><b>${esc(n)}</b> ${esc(c.unit)}<br><small>${esc(c.book)} ${esc(c.pages)}</small></p>`).join(''))}if(tab==='table')root.insertAdjacentHTML('beforeend',coursePanel());if(tab==='dates')root.insertAdjacentHTML('beforeend',examPanels());if(tab==='review')root.insertAdjacentHTML('afterbegin',reviewPanels()),root.insertAdjacentHTML('beforeend',questionPanel());if(tab==='focus')root.insertAdjacentHTML('afterbegin',focusExtra()),root.insertAdjacentHTML('beforeend',learningPanel());};
function commit(message){if(persist()){render();if(message)notice(message)}}
document.addEventListener('submit',e=>{const f=e.target,k=f.dataset.plus;if(!k)return;e.preventDefault();const d=new FormData(f),id=f.dataset.id;if(k==='course'){plus.courses[f.dataset.subject]={book:clean(d.get('book')==='__custom'?d.get('bookCustom'):d.get('book'),80),unit:clean((d.get('unit')==='__custom'||!d.get('unit'))&&d.get('unitCustom')?d.get('unitCustom'):(d.get('unit')==='__custom'?'':d.get('unit')),100),pages:clean(d.get('pages'),40)}}if(k==='exam'){const eventDate=String(d.get('date'));if(!valid(eventDate))return;const event=state.dates.find(x=>x.id===id);if(event){event.date=eventDate;save()}const m=plus.exams[id]||{steps:[]},lines=String(d.get('units')||'').split('\n').map(s=>s.trim()).filter(Boolean).map(s=>s.slice(0,120)),unique=lines.filter((s,i)=>lines.indexOf(s)===i&&!m.steps.some(x=>x.title===s));if(m.steps.length+unique.length>30){notice('계획은 일정마다 30단계까지 넣을 수 있어.');return}plus.exams[id]={steps:[...m.steps,...unique.map(title=>({title,done:false}))],rubric:clean(d.get('rubric'))}}if(k==='review'){if(!valid(String(d.get('due'))))return;const x=state.reviews.find(x=>x.id===id);if(!x)return;plus.reviews[id]={...reviewMeta(x),cause:String(d.get('cause')),source:clean(d.get('source'),120),due:String(d.get('due'))}}if(k==='goal')plus.goal=clean(d.get('goal'),120);if(k==='reflection'){const explanation=clean(d.get('explanation'),400).trim();if(!explanation)return;plus.logs.push({date:today(),goal:plus.goal,explanation,feeling:String(d.get('feeling'))});plus.logs=plus.logs.slice(-200)}if(k==='question'){const title=clean(d.get('title'),200).trim();if(!title)return;if(plus.questions.length>=100){notice('질문은 최대 100개야. 기존 질문에 답변을 정리해줘.');return}plus.questions.push({id:uid(),date:today(),title,answer:'',done:false})}if(k==='answer'){const x=plus.questions.find(x=>x.id===id);if(x){x.answer=clean(d.get('answer'));x.done=!!d.get('done')}}commit('저장했어 🐾')});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.step){const s=plus.exams[t.dataset.step]?.steps[Number(t.dataset.index)];if(s){s.done=t.checked;persist();const box=t.closest('details'),steps=plus.exams[t.dataset.step].steps;box.querySelector('progress').value=steps.filter(x=>x.done).length;box.querySelector('progress').previousElementSibling.textContent=steps.filter(x=>x.done).length+'/'+steps.length+'단계 완료'}}if(t.hasAttribute('data-subject-choice')){plus.subject=t.value;persist();const panel=t.closest('details');panel.querySelector('ol').innerHTML=routes[plus.subject].map(s=>`<li>${s}</li>`).join('')}if(t.dataset.check&&tab==='today')render()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-today-task'))document.querySelector('#task')?.focus();if(b.dataset.mode){plus.mode=Number(b.dataset.mode);commit()}if(b.dataset.carry||b.dataset.finish){const x=state.tasks.find(x=>x.id===(b.dataset.carry||b.dataset.finish));if(x){if(b.dataset.carry)x.date=today();else x.done=true;save();render()}}if(b.dataset.template){const x=state.dates.find(x=>x.id===b.dataset.template);if(!x)return;plus.exams[x.id]={rubric:plus.exams[x.id]?.rubric||'',steps:(x.kind==='시험'?['시험 범위 확인','개념·대표 문제','오답 다시 풀기','서술형·시간 연습','핵심 정리']:['주제 결정','자료·출처 확인','초안 만들기','연습·검토','제출 확인']).map(title=>({title,done:false}))};commit('기본 단계를 넣었어. 필요한 세부 내용도 추가해봐.')}if(b.dataset.result){const x=state.reviews.find(x=>x.id===b.dataset.id);if(!x)return;plus.reviews[x.id]=nextReview(reviewMeta(x),b.dataset.result);commit('다음 복습: '+plus.reviews[x.id].due+' 🐾')}});
// Timetable auto-save stays immediate; rebuild the course list only when opened.
document.addEventListener('toggle',e=>{if(e.target.id==='course-panel'&&e.target.open){const node=document.createElement('div');node.innerHTML=coursePanel();const fresh=node.firstElementChild;e.target.innerHTML=fresh.innerHTML}},true);
window.studyPlusBridge={snapshot:()=>JSON.parse(JSON.stringify(plus)),restore:restorePlus,replace:value=>{plus=restorePlus(JSON.stringify(value))}};
render();
})();

